// Classical Sculpture 3D Geometry Data (WaltHead museum bust)
(function() {
  'use strict';
  function b64ToFloats(b64) {
    const bin = atob(b64);
    const buf = new ArrayBuffer(bin.length);
    const u8 = new Uint8Array(buf);
    for (let i = 0; i < bin.length; i++) u8[i] = bin.charCodeAt(i);
    return new Float32Array(buf);
  }
  function b64ToU16(b64) {
    const bin = atob(b64);
    const buf = new ArrayBuffer(bin.length);
    const u8 = new Uint8Array(buf);
    for (let i = 0; i < bin.length; i++) u8[i] = bin.charCodeAt(i);
    return new Uint16Array(buf);
  }

  window.createSculptureGeometry = function() {
    const geo = new THREE.BufferGeometry();
    const positions = b64ToFloats('');
    const normals = b64ToFloats('');
    const indices = b64ToU16('');
    geo.setAttribute('position', new THREE.BufferAttribute(positions, 3));
    geo.setAttribute('normal', new THREE.BufferAttribute(normals, 3));
    geo.setIndex(new THREE.BufferAttribute(indices, 1));
    return geo;
  };
})();
